// jsdom 環境で public/index.html の DOM とロジックをテストする

const fs = require('fs');
const path = require('path');

// HTML を読み込んで document に設定する
function loadHTML() {
  const html = fs.readFileSync(
    path.resolve(__dirname, '../../public/index.html'),
    'utf-8'
  );
  document.open();
  document.write(html);
  document.close();
}

// fetch をモックする
function mockFetch(responses) {
  let callIndex = 0;
  global.fetch = jest.fn(() => {
    const res = responses[callIndex++] ?? responses[responses.length - 1];
    return Promise.resolve({
      ok: res.ok ?? true,
      status: res.status ?? 200,
      json: () => Promise.resolve(res.body),
    });
  });
}

beforeEach(() => {
  // 各テスト前に HTML をリセットする
  loadHTML();
});

afterEach(() => {
  jest.resetAllMocks();
});

describe('初期表示', () => {
  test('fetch が /todos に対して呼ばれる', async () => {
    mockFetch([{ body: [] }]);

    // スクリプトの fetchAndRender() は DOMContentLoaded 後に実行される
    document.dispatchEvent(new Event('DOMContentLoaded'));

    // fetch の非同期処理が完了するまで待つ
    await new Promise((r) => setTimeout(r, 0));

    expect(global.fetch).toHaveBeenCalledWith('/todos');
  });

  test('TODO が空のとき空状態メッセージが表示される', async () => {
    mockFetch([{ body: [] }]);
    document.dispatchEvent(new Event('DOMContentLoaded'));
    await new Promise((r) => setTimeout(r, 0));

    const emptyMsg = document.getElementById('empty-msg');
    expect(emptyMsg.style.display).not.toBe('none');
  });
});

describe('TODO の追加', () => {
  test('追加ボタンをクリックすると POST /todos が呼ばれる', async () => {
    // 初期表示 → 追加の順にレスポンスを返す
    mockFetch([
      { body: [] },
      { status: 201, body: { id: 1, title: '買い物', completed: false, createdAt: '' } },
    ]);

    document.dispatchEvent(new Event('DOMContentLoaded'));
    await new Promise((r) => setTimeout(r, 0));

    document.getElementById('new-title').value = '買い物';
    document.getElementById('add-btn').click();
    await new Promise((r) => setTimeout(r, 0));

    expect(global.fetch).toHaveBeenCalledWith('/todos', expect.objectContaining({
      method: 'POST',
      body: JSON.stringify({ title: '買い物' }),
    }));
  });
});

